CREATE TABLE job_agent.application_tracker(id UUID PRIMARY KEY,user_id VARCHAR(150) NOT NULL,job_posting_id UUID NOT NULL REFERENCES job_agent.job_posting(id) ON DELETE RESTRICT,application_handoff_id UUID NOT NULL UNIQUE REFERENCES job_agent.application_handoff(id) ON DELETE RESTRICT,application_package_revision_id UUID NOT NULL REFERENCES job_agent.application_package_revision(id) ON DELETE RESTRICT,job_evaluation_id UUID NOT NULL REFERENCES job_agent.job_evaluation(id) ON DELETE RESTRICT,current_status VARCHAR(30) NOT NULL CHECK(current_status IN ('SUBMITTED','ACKNOWLEDGED','UNDER_REVIEW','ASSESSMENT','INTERVIEW','OFFER','REJECTED','WITHDRAWN','EXPIRED')),submitted_reported_at TIMESTAMPTZ NOT NULL,last_activity_at TIMESTAMPTZ NOT NULL,archived_at TIMESTAMPTZ,record_version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_tracker_user_activity ON job_agent.application_tracker(user_id,last_activity_at DESC);
CREATE TABLE job_agent.application_timeline_event(id UUID PRIMARY KEY,application_tracker_id UUID NOT NULL REFERENCES job_agent.application_tracker(id) ON DELETE RESTRICT,event_type VARCHAR(40) NOT NULL,previous_status VARCHAR(30),new_status VARCHAR(30),source VARCHAR(30) NOT NULL,note VARCHAR(1000),created_by VARCHAR(150) NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_tracker_event_created ON job_agent.application_timeline_event(application_tracker_id,created_at);
